SELECT m.id, m.author, m.content, m.created_at, ub.username AS author_name, ua.nickname AS author_nickname FROM message_board m LEFT JOIN user_basic ub ON m.author = ub.uuid LEFT JOIN user_archive ua ON m.author = ua.uuid
AND (m.author LIKE CONCAT('%', #{condition.keyword}, '%') OR ub.username LIKE CONCAT('%', #{condition.keyword}, '%') OR ua.nickname LIKE CONCAT('%', #{condition.keyword}, '%'))
AND m.content LIKE CONCAT('%', #{condition.content}, '%')
AND m.created_at >= #{condition.date_from}
AND m.created_at <= #{condition.date_to}
ORDER BY m.created_at DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM message_board m LEFT JOIN user_basic ub ON m.author = ub.uuid LEFT JOIN user_archive ua ON m.author = ua.uuid
AND (m.author LIKE CONCAT('%', #{condition.keyword}, '%') OR ub.username LIKE CONCAT('%', #{condition.keyword}, '%') OR ua.nickname LIKE CONCAT('%', #{condition.keyword}, '%'))
AND m.content LIKE CONCAT('%', #{condition.content}, '%')
AND m.created_at >= #{condition.date_from}
AND m.created_at <= #{condition.date_to}
